{"check_build":{"code":"script({title:'Cinderwing and the Last Ember',description:'A great obsidian dragon crouches around its glowing egg, flaring enormous scalloped crimson wings. Ivory horns, hooked claws, an open fanged jaw and a curling armoured tail frame the ember-orange throat.',palette:{scale:'black',web:'dark red',heat:'orange',bone:'tan',rock:'dark bluish grey'}});
const P=(part,x,y,z,colour='scale',turn=0)=>place({part,at:[x,y,z],colour,turn});
const B=(x,y,z,w,h,d,colour='scale')=>box({at:[x,y,z],size:[w,h,d],colour,interior:'solid'});
const F=(x,y,z,w,d,layers=1,colour='scale',tile=false)=>floor({at:[x,y,z],size:[w,d],layers,colour,...(tile?{top:'tile'}:{})});
function foot(x,z){const a=[F(x,0,z,6,8,2,'scale',true),B(x,2,z+2,6,3,6)];for(let i=0;i<3;i++){a.push(P('11477',x+2*i,2,z),P('49668',x+2*i+1,2,z,'bone'));for(let j=0;j<3;j++)a.push(P('15068',x+2*i,5,z+2+2*j,j===0?'web':'scale'));}return a;}
function haunch(x,z){const a=[B(x+1,5,z,2,18,6)];for(let y=8;y<23;y+=3)for(let j=0;j<3;j++)a.push(P('15068',x,y,z+2*j,'web',90),P('15068',x+2,y,z+2*j,'web',270));a.push(P('93606',x+1,23,z,'scale'),P('15068',x,23,z+4,'scale',180),P('15068',x+2,23,z+4,'scale',180));return a;}
function foreleg(x,z){const a=[B(x+1,5,z+4,2,9,4),B(x+1,11,z+7,2,15,4),B(x,20,z+8,4,6,5)];for(const y of [8,11])for(const q of [4,6])a.push(P('15068',x,y,z+q,'web',90),P('15068',x+2,y,z+q,'web',270));for(const y of [14,17,20,23])for(const q of [7,9])a.push(P('15068',x,y,z+q,'scale',90),P('15068',x+2,y,z+q,'scale',270));a.push(P('93606',x+1,26,z+7,'scale'));return a;}
section('Four planted clawed feet and muscular limbs',[...foot(-11,9),...foot(5,10),...foot(-8,-7),...foot(4,-10),...haunch(-10,11),...haunch(6,12),...foreleg(-8,-7),...foreleg(4,-10),B(-7,14,11,3,9,6,'web'),B(4,14,12,4,9,6,'web')]);
const body=[box({at:[-5,12,1],size:[10,21,15],colour:'scale',interior:'empty'}),F(-5,12,0,10,18,3),F(-3,32,2,6,14,1,'scale',true)];
for(const s of [-1,1])for(let z=2;z<=14;z+=2){const x=s<0?-7:5,t=s<0?90:270;const covered=y=>s<0?((z===2&&y<27)||(z>=10&&y<24)):(z>=12&&y<24);if(!covered(12))body.push(P('3660b',x,12,z,'web',t));for(let y=15;y<=27;y+=3)if(!covered(y))body.push(P('15068',x,y,z,y===27?'scale':'web',t));}
for(let y=15;y<=30;y+=3)for(let x=-4;x<=2;x+=2)body.push(P('15068',x,y,0,y%6===0?'heat':'dark orange'));
for(let y=15;y<=30;y+=3)for(let x=-4;x<=2;x+=2)if(!(y<21&&(x===-2||x===0)))body.push(P('15068',x,y,16,'scale',180));
for(let z=2;z<=14;z+=2)body.push(P('15068',-5,30,z,'scale',90),P('15068',3,30,z,'scale',270));
for(const z of [9,12,15])body.push(P('3040b',-1,33,z,'scale',180),P('15070',0,33,z,'bone'));
section('Rounded cuirass and segmented ember belly',body);
const neck=[B(-3,30,0,6,18,6),B(-3,45,-3,6,15,6),F(-3,30,-2,6,8,3),F(-3,45,-5,6,8,3)];
for(let y=33;y<=45;y+=3){for(const x of [-2,0])neck.push(P('15068',x,y,-2,'heat'),P('15068',x,y,6,'scale',180));for(const z of [0,2,4])neck.push(P('15068',-4,y,z,'scale',90),P('15068',2,y,z,'scale',270));}
for(let y=48;y<=57;y+=3){for(const x of [-2,0])neck.push(P('15068',x,y,-5,y%6===0?'heat':'dark orange'),P('15068',x,y,3,'scale',180));for(const z of [-3,-1,1])neck.push(P('15068',-4,y,z,'web',90),P('15068',2,y,z,'web',270));}
section('Sweeping S neck',neck);
const head=[B(-4,60,-10,8,6,8),B(-2,53,-12,4,3,9),F(-3,56,-15,6,15,3),F(-2,59,-14,4,10,1,'web',true),F(-3,63,-16,6,8,2),F(-5,66,-4,10,3,2,'scale',true)];
for(let x=-3;x<3;x++)head.push(P('61678',x,53,-15),P('61678',x,65,-16),P('11477',x,65,-12));
for(const x of [-3,2]){for(const z of [-13,-11,-7,-5])head.push(P('3069b',x,59,z,'scale',90));for(const z of [-14,-8])head.push(P('4589',x,59,z,'white'));head.push(P('3040b',x,60,-11,'white'));}
for(const z of [-8,-6,-4])head.push(P('3660b',-5,60,z,'scale',90),P('3660b',3,60,z,'scale',270),P('15068',-5,63,z,'web',90),P('15068',3,63,z,'web',270));
for(const x of [-2,0])for(const z of [-10,-8,-6])head.push(P('15068',x,66,z));
for(const x of [-4,3])head.push(P('3005',x,66,-10,'trans yellow'),P('3024',x,69,-10,'scale'),P('11477',x,70,-10,'scale'));
head.push(P('15068',-4,66,-9,'web'),P('15068',2,66,-9,'web'));
for(const x of [-5,3])head.push(P('3942c',x,68,-4,'bone'),P('4589',x+(x>0?1:0),74,-4,'bone'));
for(const x of [-3,-1,1])head.push(P('15068',x,68,-4));
head.push(P('15070',-1,71,-3,'bone'));
for(const x of [-2,1])head.push(P('6141',x,68,-13,'dark bluish grey'),P('98138',x,69,-13,'scale'));
section('Horned head, glowing eyes and open fanged jaw',head);
function tailSegment(x,y,z,w,d,h,turn=0){const a=[B(x,y,z,w,h-3,d)];for(let i=0;i<w;i+=2)for(let j=0;j<d;j+=2)a.push(P('15068',x+i,y+h-3,z+j,(i===0||i===w-2)?'web':'scale',turn));return a;}
const tail=[...tailSegment(-3,9,16,6,8,9,180),...tailSegment(-2,5,24,4,6,8,180),...tailSegment(2,2,28,10,4,7,270),...tailSegment(12,1,24,6,8,6),...tailSegment(16,0,18,4,6,6),F(-2,9,22,4,4),F(0,5,28,8,2),F(10,3,28,6,2),F(16,1,22,2,4),F(16,0,12,2,8),P('61678',16,1,12,'web'),P('61678',17,1,12,'web'),P('15068',16,1,16,'web')];
for(const [x,y,z] of [[-1,18,20],[0,13,26],[6,9,29],[13,7,28],[17,6,20]])tail.push(P('15070',x,y,z,'bone'));
section('Ground hugging hooked tail',tail);
const low=[33,33,36,42,45,42,36,42,48,51,51,51],top=[42,48,54,60,66,72,72,69,66,63,60,57];
function wing(side,z,dy){const a=[B(side<0?-9:5,30+dy,z,4,6,2)];const X=i=>side>0?7+2*i:-9-2*i;for(let i=0;i<12;i++){const x=X(i),lo=low[i]+dy,cap=top[i]+dy-(i<6?6:3);a.push(P('3660b',x,lo,z,'scale',side>0?270:90));if(cap>lo+3)a.push(B(x,lo+3,z,2,cap-lo-3,2,'web'));for(let y=lo+3;y<cap;y+=3){const rib=i===4||i===8;const c=rib?'scale':(y===cap-3&&i<6?'dark orange':'web');a.push(P('3004',x,y,z,c));}a.push(P(i<6?'3678b':'3039',x,cap,z,'scale',side>0?(i<6?90:270):(i<6?270:90)));}
for(let y=33+dy;y<72+dy;y+=3){const valid=i=>y>=low[i]+dy+3&&y+3<=top[i]+dy-(i<6?6:3);let i=0;while(i<12){if(!valid(i)){i++;continue;}let n=1;if(valid(i+1)&&i+1<12&&Math.floor((y-dy)/3)%2===0)n=2;const x=side>0?X(i):X(i+n-1);a.push(P(n===2?'3010':'3004',x,y,z+1,(i===4||i===8)?'scale':'web'));i+=n;}}
a.push(P('3942c',side>0?17:-19,top[5]+dy,z,'bone'));
return a;}
section('Towering scalloped bat wings',[...wing(-1,9,0),...wing(1,11,-3)]);
section('The last ember egg',[F(10,0,-12,8,8,1,'rock',true),cylinder({at:[11,1,-11],diameter:6,height:6,colour:'heat'}),dome({at:[11,7,-11],diameter:6,colour:'heat'}),...[[10,-12],[16,-12],[10,-6],[16,-6]].map(([x,z])=>P('15068',x,1,z,'rock'))]);","seed":1}}

